CREATE COLUMN TABLE "TEST_AP"."OWPK" ("AbsEntry" INTEGER CS_INT NOT NULL , "PackagCode" NVARCHAR(32) NOT NULL , "PackagName" NVARCHAR(100), "Note" NCLOB MEMORY THRESHOLD 1000, "Content" BLOB MEMORY THRESHOLD 1000, "Author" NVARCHAR(32), "Version" NVARCHAR(13), "CreateDate" LONGDATE CS_LONGDATE, "CreateTime" SMALLINT CS_INT, "IsSystem" NVARCHAR(1) DEFAULT 'N', "PackagType" NVARCHAR(1) DEFAULT 'D', "ISIMDB" NVARCHAR(1) DEFAULT 'N', "StraType" NVARCHAR(254) DEFAULT 'none', "StraPara" NVARCHAR(254), "SourceType" NVARCHAR(20) DEFAULT 'normal', "ViewName" NVARCHAR(250), "ViewCtg" NVARCHAR(250), "ViewSyn" NVARCHAR(250), "Viewid" INTEGER CS_INT, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OWPK_CODE" ON "TEST_AP"."OWPK" ( "PackagCode" ASC )